import type { ComponentPropsWithoutRef, ReactNode } from "react";
import { cn } from "../../lib/cn";
import "../../styles/breadcrumb.css";

/** Location trail. Mark the last item with `BreadcrumbCurrent` so it is announced as the current page. */
export function Breadcrumb({ className, ...props }: ComponentPropsWithoutRef<"nav">) {
  return <nav aria-label="Breadcrumb" className={cn("eui-breadcrumb", className)} {...props} />;
}

export function BreadcrumbList({ className, ...props }: ComponentPropsWithoutRef<"ol">) {
  return <ol className={cn("eui-breadcrumb__list", className)} {...props} />;
}

export function BreadcrumbItem({ className, ...props }: ComponentPropsWithoutRef<"li">) {
  return <li className={cn("eui-breadcrumb__item", className)} {...props} />;
}

export function BreadcrumbLink({ className, children, ...props }: ComponentPropsWithoutRef<"a">) {
  // Children are passed explicitly so the anchor-has-content lint rule can see them.
  return (
    <a className={cn("eui-breadcrumb__link", className)} {...props}>
      {children}
    </a>
  );
}

export function BreadcrumbCurrent({
  className,
  children,
  ...props
}: ComponentPropsWithoutRef<"span"> & { children?: ReactNode }) {
  return (
    <span aria-current="page" className={cn("eui-breadcrumb__current", className)} {...props}>
      {children}
    </span>
  );
}

/** Decorative divider between items. Hidden from assistive tech. */
export function BreadcrumbSeparator() {
  return (
    <span className="eui-breadcrumb__separator" aria-hidden="true">
      /
    </span>
  );
}

/**
 * Joins class names, skipping falsy values.
 * Kept tiny on purpose: components own their class lists, so no merge step is needed.
 */
export function cn(...inputs: Array<string | false | null | undefined>): string {
  return inputs.filter(Boolean).join(" ");
}

/* Breadcrumb. A single wrapping row. The current page is plain text, not a link. */

.eui-breadcrumb__list {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: 13px;
}

.eui-breadcrumb__item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}

.eui-breadcrumb__link {
  min-height: 24px;
  display: inline-flex;
  align-items: center;
  color: var(--eui-color-fg-muted);
  text-decoration: none;
  border-radius: var(--eui-radius-sm);
}

.eui-breadcrumb__link:hover {
  color: var(--eui-color-fg);
  text-decoration: underline;
  text-underline-offset: 3px;
}

.eui-breadcrumb__link:focus-visible {
  outline: 2px solid var(--eui-color-ring);
  outline-offset: 2px;
}

.eui-breadcrumb__current {
  color: var(--eui-color-fg);
  font-weight: 500;
}

.eui-breadcrumb__separator {
  color: var(--eui-color-border-strong);
}
